#!/usr/bin/env python3
"""Regenerate the generated examples in analyzer/docs/output.md.

The output is the analyzer's own; the input is the synthetic collection of host `wsdev14` that
`example_collection.py` builds in a temporary directory. The tool runs the analyzer's `detect`,
`detect --json` and `timeline -o <work>/out` on it in this process, and puts the
output between the marker comments of each example block, here `detect-text`:

    <!-- generated by analyzer/tools/regenerate_examples.py: detect-text -->
    <!-- end generated: detect-text -->

The blocks, in document order: `detect-text` and `detect-json` (the two `detect` stdouts),
`timeline-stdout`, then the three files `timeline` wrote, `inventory-json`, `timeline-jsonl`
and `sessions-jsonl`. `timeline-jsonl` is the `timeline.jsonl` of a second run with the filters
`TIMELINE_FILTERS`, so it stays short enough to read and still holds every documented row form.

    python3 analyzer/tools/regenerate_examples.py           # rewrite the document
    python3 analyzer/tools/regenerate_examples.py --check   # exit 1 when a block is stale

The collection's temporary path is printed as `/cases/wsdev14/wsdev14` and the output directory as
`out`; every other byte is what the run wrote. Every time in the collection is fixed, so the
shown output is the same on every run. "The example collection" in
analyzer/docs/output.md describes the collection, "Regenerating the output examples" in
analyzer/docs/development.md the options. A symbolic-link `--document` is followed, so its
target is rewritten.

Exit status: 0 when the document is current or was rewritten, 1 when `--check` found a stale
block, 2 when the marker lines are not each block's begin and end, in order, the document
cannot be read or is not UTF-8 with LF line ends, a run fails, or the new file cannot be
written. Only the text between the markers changes, and the file is replaced in one rename.
"""

from __future__ import annotations

import argparse
import contextlib
import difflib
import io
import json
import os
import stat
import sys
import tempfile
from pathlib import Path

TOOLS = Path(__file__).resolve().parent
ANALYZER = TOOLS.parent
for directory in (ANALYZER, TOOLS):
    if str(directory) not in sys.path:
        sys.path.insert(0, str(directory))

# Imported after the analyzer and tools directories join the path, so the tool runs from any
# directory.
from example_collection import build_collection  # noqa: E402

from doubleagent import cli  # noqa: E402
from doubleagent.errors import DoubleAgentError  # noqa: E402

DOCUMENT = ANALYZER / "docs" / "output.md"
SHOWN_INPUT = "/cases/wsdev14/wsdev14"
SHOWN_OUTPUT = "out"
OUTPUT_FILES = ("timeline.jsonl", "sessions.jsonl", "inventory.json")
BLOCKS = (
    "detect-text",
    "detect-json",
    "timeline-stdout",
    "inventory-json",
    "timeline-jsonl",
    "sessions-jsonl",
)
# The fence language of each block; the rest are `json`.
TEXT_BLOCKS = {"detect-text", "timeline-stdout"}
# The filters of the run whose `timeline.jsonl` is shown: three agents, and the row forms the
# document points out, a matched tool call keeping its result.
TIMELINE_FILTERS = (
    "--agent",
    "claude-code",
    "--agent",
    "codex-cli",
    "--agent",
    "cursor",
    "--match",
    r"^(permission (decision|mode)|permission setting: permissions\.(allow|defaultMode)"
    r"|model: \S+ -> |session (origin|synced)|remote control: environment|scratch directory"
    r"|git remote|thread record|source host: github account|parser: unparseable|slash command"
    r"|an older prompt)|Begin Patch",
)
BEGIN = "<!-- generated by analyzer/tools/regenerate_examples.py: %s -->"
END = "<!-- end generated: %s -->"


class MarkerError(DoubleAgentError):
    """The marker lines are not each block's begin and end, in order."""


class DocumentError(DoubleAgentError):
    """The document is not UTF-8 text with LF line ends, so a rewrite could change other text."""


class RunError(DoubleAgentError):
    """An analyzer command exited with a failure, so its output is no example."""


def _run(argv: list[str]) -> str:
    stdout, stderr = io.StringIO(), io.StringIO()
    try:
        with contextlib.redirect_stdout(stdout), contextlib.redirect_stderr(stderr):
            status = cli.main(argv)
    except Exception as error:
        # Whatever a parser raises, the run produced no example; exit 1 would read as stale.
        raise RunError("%s raised %r" % (argv[0], error)) from error
    if status != 0:
        raise RunError("%s exited %s: %s" % (argv[0], status, stderr.getvalue().strip()))
    return stdout.getvalue()


def _show_paths(text: str, collection: Path, out: Path) -> str:
    """Return `text` with the temporary paths replaced by the ones the document shows.

    Each output file path becomes `out/<name>`, then the output directory `out` and the
    collection `/cases/wsdev14/wsdev14`, each in its JSON-escaped and its raw form.
    """
    shown = {str(out / name): SHOWN_OUTPUT + "/" + name for name in OUTPUT_FILES}
    shown[str(out)] = SHOWN_OUTPUT
    shown[str(collection)] = SHOWN_INPUT
    # Both spellings of each path: on macOS the temporary /var/... resolves to /private/var/...
    forms: dict[str, str] = {}
    for real, display in shown.items():
        for path in (real, str(Path(real).resolve())):
            forms[json.dumps(path)[1:-1]] = display
            forms[path] = display
    # Longest first, so a file path is replaced before the directory it starts with.
    for form in sorted(forms, key=len, reverse=True):
        text = text.replace(form, forms[form])
    return text


def generate() -> dict[str, str]:
    """Run the analyzer on a fresh `wsdev14` collection.

    Returns:
        Each name of `BLOCKS` mapped to its fenced block, ending with a line feed: `text` for
        the plain `detect` and the `timeline` stdout, `json` for the `detect --json` stdout and
        each file `timeline` wrote (`timeline.jsonl` the filtered run's), one record per line.

    Raises:
        RunError: A `detect` or `timeline` run failed.
    """
    with tempfile.TemporaryDirectory(prefix="doubleagent-examples-") as work:
        collection = build_collection(Path(work))
        out = Path(work) / "out"
        outputs = {
            "detect-text": _run(["detect", str(collection)]),
            "detect-json": _run(["detect", str(collection), "--json"]),
            "timeline-stdout": _run(["timeline", str(collection), "-o", str(out)]),
        }
        for name in OUTPUT_FILES:
            block = name.replace(".", "-")
            outputs[block] = (out / name).read_text(encoding="utf-8")
        shown = Path(work) / "shown"
        _run(["timeline", str(collection), "-o", str(shown), *TIMELINE_FILTERS])
        outputs["timeline-jsonl"] = (shown / "timeline.jsonl").read_text(encoding="utf-8")
        blocks = {}
        for name in BLOCKS:
            language = "text" if name in TEXT_BLOCKS else "json"
            text = _show_paths(outputs[name], collection, out).rstrip("\n")
            blocks[name] = "```%s\n%s\n```\n" % (language, text)
        return blocks


def _spans(text: str) -> dict[str, tuple[int, int]]:
    """Return each block's start and end offsets, between its marker lines.

    The marker lines of `text`, every line starting like a begin or an end marker, must be
    exactly each block's begin and end in `BLOCKS` order, so blocks can never nest or overlap.

    Raises:
        MarkerError: The marker lines are any other sequence.
    """
    expected = [marker % name for name in BLOCKS for marker in (BEGIN, END)]
    prefixes = (BEGIN.split("%s")[0], END.split("%s")[0])
    found: list[tuple[str, int, int]] = []
    offset = 0
    for line in text.split("\n"):
        if line.startswith(prefixes):
            found.append((line, offset, offset + len(line) + 1))
        offset += len(line) + 1
    if [line for line, _, _ in found] != expected:
        raise MarkerError(
            "markers must be these lines, in order: %s; found: %s"
            % (", ".join(expected), ", ".join(line for line, _, _ in found) or "none")
        )
    return {name: (found[2 * i][2], found[2 * i + 1][1]) for i, name in enumerate(BLOCKS)}


def render(text: str, blocks: dict[str, str]) -> str:
    """Return `text` with each block's markers enclosing its new content.

    Raises:
        MarkerError: The marker lines are not each block's begin and end, in order.
    """
    spans = _spans(text)
    for name in reversed(BLOCKS):
        start, stop = spans[name]
        text = text[:start] + blocks[name] + text[stop:]
    return text


def _read(document: Path) -> str:
    """Return `document` as text, exactly as stored.

    Raises:
        DocumentError: It is not UTF-8 or holds a carriage return.
    """
    try:
        text = document.read_bytes().decode("utf-8")
    except UnicodeDecodeError as error:
        raise DocumentError("%s is not UTF-8: %s" % (document, error)) from error
    if "\r" in text:
        raise DocumentError("%s holds a carriage return; only LF line ends are kept" % document)
    return text


def _write(document: Path, text: str) -> None:
    """Replace `document` with `text` in one rename, keeping its mode; a failure leaves it whole."""
    mode = stat.S_IMODE(document.stat().st_mode)
    descriptor, name = tempfile.mkstemp(dir=document.parent, prefix=document.name + ".")
    try:
        with os.fdopen(descriptor, "wb") as handle:
            handle.write(text.encode("utf-8"))
        os.chmod(name, mode)
        os.replace(name, document)
    except BaseException:
        os.unlink(name)
        raise


def check(document: Path = DOCUMENT) -> list[str]:
    """Return a unified diff per stale block of `document`, empty when every block is current.

    Raises:
        MarkerError: The marker lines are not each block's begin and end, in order.
        DocumentError: The document is not UTF-8 or holds a carriage return.
        RunError: The `detect` or `timeline` run failed.
    """
    text = _read(document)
    spans = _spans(text)
    blocks = generate()
    diffs = []
    for name in BLOCKS:
        start, stop = spans[name]
        if text[start:stop] != blocks[name]:
            lines = difflib.unified_diff(
                text[start:stop].splitlines(keepends=True),
                blocks[name].splitlines(keepends=True),
                "%s (%s, documented)" % (document, name),
                "%s (%s, regenerated)" % (document, name),
            )
            diffs.append("".join(lines))
    return diffs


def regenerate(document: Path = DOCUMENT) -> None:
    """Rewrite every generated block of `document` from a fresh run.

    Raises:
        MarkerError: The marker lines are not each block's begin and end, in order.
        DocumentError: The document is not UTF-8 or holds a carriage return.
        RunError: The `detect` or `timeline` run failed.
    """
    document = document.resolve()
    text = render(_read(document), generate())
    _write(document, text)


def main(argv: list[str] | None = None) -> int:
    """Run the command line and return the exit status."""
    parser = argparse.ArgumentParser(description="Regenerate the generated examples of output.md.")
    parser.add_argument("--check", action="store_true", help="report stale blocks, write nothing")
    parser.add_argument("--document", type=Path, default=DOCUMENT, help="default: %(default)s")
    args = parser.parse_args(argv)
    try:
        if not args.check:
            regenerate(args.document)
            return 0
        diffs = check(args.document)
    except (MarkerError, DocumentError, RunError, OSError) as error:
        print("error: %s" % error, file=sys.stderr)
        return 2
    for diff in diffs:
        sys.stdout.write(diff)
    if diffs:
        print("stale; run python3 analyzer/tools/regenerate_examples.py", file=sys.stderr)
    return 1 if diffs else 0


if __name__ == "__main__":
    sys.exit(main())
